        F("Жинақсыздық", r"a_n\not\to a\iff\exists\varepsilon>0\ \forall N\ \exists n\ge N:\ |a_n-a|\ge\varepsilon", r"Кванторлардың теріске шығаруы.", r""),
        F("Коши шарты", r"\forall\varepsilon>0\ \exists N\ \forall m,n\ge N:\ |a_m-a_n|&lt;\varepsilon", r"$\mathbb R$-де жинақтылыққа тең күшті.", r""),
